<script setup lang="ts">
/**
 * Demo: SnVideoPreview — expand the thumbnail into the full-screen overlay.
 * The overlay closes with Esc, a mask click or the close button; the same can
 * be triggered imperatively through the exposed `showPreview()` method.
 */
import { ref } from 'vue';
import { SnButton, SnVideoPreview } from '@snui/vue-web';

/** 自包含视频源（data URI，Web Platform Tests media/2x2-green.mp4，BSD-3-Clause）。 */
const videoSrc =
  'data:video/mp4;base64,';

function poster(from: string, to: string, label = '', w = 640, h = 360): string {
  const parts = [
    `<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="${h}">`,
    `<defs><linearGradient id="g" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="${from}"/><stop offset="1" stop-color="${to}"/></linearGradient></defs>`,
    `<rect width="${w}" height="${h}" fill="url(#g)"/>`,
    `<circle cx="${w * 0.78}" cy="${h * 0.26}" r="${h * 0.26}" fill="rgba(255,255,255,0.16)"/>`,
  ];
  if (label) {
    parts.push(
      `<text x="50%" y="52%" fill="rgba(255,255,255,0.92)" font-family="system-ui,sans-serif" font-size="${Math.round(h * 0.1)}" font-weight="600" text-anchor="middle" dominant-baseline="middle">${label}</text>`,
    );
  }
  parts.push('</svg>');
  return `data:image/svg+xml;charset=utf-8,${encodeURIComponent(parts.join(''))}`;
}

const videoPreviewRef = ref<{ showPreview: () => void } | null>(null);

function openPreview(): void {
  videoPreviewRef.value?.showPreview();
}
</script>

<template>
  <div class="demo-col">
    <div class="demo-row">
      <SnVideoPreview
        ref="videoPreviewRef"
        :src="videoSrc"
        :poster="poster('#85a5ff', '#1d39c4', 'Promo film')"
        title="Promo video · Fullscreen preview"
      />
      <SnVideoPreview
        :src="videoSrc"
        :poster="poster('#ffc069', '#d46b08', 'Preview disabled')"
        title="Preview disabled"
        preview-disabled
      />
    </div>
    <SnButton type="primary" size="small" @click="openPreview"
      >Open the preview via showPreview()</SnButton
    >
  </div>
</template>

